mcp-registry.canonical:
// npm-package/server.json
{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "categories": [
    "web-search",
    "web-scraping",
    "research",
    "data-extraction"
  ],
  "packages": [
    {
      "environmentVariables": [
        {
          "description": "Your Novada API key from https://www.novada.com",
          "format": "string",
          "isRequired": true,
          "isSecret": true,
          "name": "NOVADA_API_KEY"
        }
      ],
      "identifier": "novada-mcp",
      "registryType": "npm",
      "transport": {
        "type": "stdio"
      },
      "version": "0.9.42"
    }
  ],
  "prompts": [
    {
      "description": "Deep multi-source research on any topic with optional country and focus constraints",
      "name": "research_topic"
    },
    {
      "description": "Extract content from one or more URLs and prepare a focused summary",
      "name": "extract_and_summarize"
    },
    {
      "description": "Map a website structure then extract and summarize key sections",
      "name": "site_audit"
    },
    {
      "description": "Scrape structured data from a specific platform (Amazon, Walmart, TikTok, LinkedIn, etc.) using the Novada Scraper API",
      "name": "scrape_platform_data"
    },
    {
      "description": "Automate a multi-step browser workflow with persistent session state (login, form submission, paginated scraping)",
      "name": "browser_stateful_workflow"
    }
  ],
  "remotes": [
    {
      "headers": [
        {
          "description": "Bearer <NOVADA_API_KEY>",
          "isRequired": true,
          "isSecret": true,
          "name": "Authorization"
        }
      ],
      "type": "streamable-http"
    }
  ],
  "repository": {
    "source": "github",
    "url": "https://github.com/NovadaLabs/novada-mcp"
  },
  "resources": [
    {
      "description": "List of search engines available in novada_search with characteristics and recommended use cases",
      "name": "Supported Search Engines",
      "uri": "novada://engines"
    },
    {
      "description": "Country codes for geo-targeted search in novada_search. 195 countries supported.",
      "name": "Supported Country Codes",
      "uri": "novada://countries"
    },
    {
      "description": "Decision tree and workflow patterns for choosing between all 37 novada tools: search, extract, crawl, map, research, site_copy, scrape (+14 per-platform scrapers), proxy, verify, browser, monitor, account, setup, discover",
      "name": "Agent Tool Selection Guide",
      "uri": "novada://guide"
    },
    {
      "description": "Full list of platforms supported by novada_scrape with their operation IDs and required parameters. Read this before calling novada_scrape to find the correct platform and operation for your use case.",
      "name": "Supported Scraper Platforms",
      "uri": "novada://scraper-platforms"
    }
  ],
  "skills": [
    {
      "description": "Tool selection guide for all 37 Novada MCP tools — decision tree, key parameters, common workflows, and when NOT to use each tool.",
      "name": "novada-agent",
      "path": "skills/novada-agent/SKILL.md"
    }
  ],
  "tools": [
    {
      "description": "Search the web for clean, ready-to-use content — titles, URLs, snippets, reranked by relevance. For multi-source questions, use novada_research instead (faster, more thorough).",
      "name": "novada_search"
    },
    {
      "description": "Extract content from any URL. Auto-handles Cloudflare/DataDome/Kasada via escalation (static → JS render → Browser CDP).",
      "name": "novada_extract"
    },
    {
      "description": "Use when you need content from a bounded set of pages (up to 20) and don't have the URLs yet. Crawls BFS/DFS, extracts each page inline.",
      "name": "novada_crawl"
    },
    {
      "description": "One call → 3-10 parallel searches across Google/Bing/DuckDuckGo → dedup → extracts full content from top sources → returns CITED SOURCE MATERIAL (numbered passages), not a written answer. Extractive, not generative — you compose the final answer from the gathered passages.",
      "name": "novada_research"
    },
    {
      "description": "Discover URLs on a site before deciding what to read. Tries sitemap.xml first (fast), falls back to BFS crawl.",
      "name": "novada_map"
    },
    {
      "description": "Copy an entire docs site/section to disk as clean markdown — one.md file per page — returning a COMPACT manifest, not page bodies. Use for a whole knowledge base on disk (offline docs ingest, RAG corpus, full-site mirror).",
      "name": "novada_site_copy"
    },
    {
      "description": "Use for structured data from a specific platform — clean tabular records, not raw HTML. Proxies the Novada Scraper API (scraper.novada.com; public docs: https://developer.novada.com/novada/advanced-proxy-solutions/scraper-api/target-sites-supported-by-scraper-api).",
      "name": "novada_scrape"
    },
    {
      "description": "Extract structured Amazon data — product details, reviews, seller info, bestseller lists, category/brand listings — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"amazon.com\").",
      "name": "novada_scrape_amazon"
    },
    {
      "description": "Extract structured Google SERP data — organic web search, AI Mode answers, Maps place/review details, Shopping, Jobs, Hotels, Videos — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"google.com\"). Returns raw structured SERP records, not a generated answer.",
      "name": "novada_scrape_google"
    },
    {
      "description": "Extract structured Bing SERP data — organic web search, video results, news results, shopping listings — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"bing.com\"). Bing is NOT a selectable engine on novada_search — this is the only intentional way to query Bing specifically.",
      "name": "novada_scrape_bing"
    },
    {
      "description": "Extract structured DuckDuckGo web search SERP data via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"duckduckgo.com\"). Returns the raw organic-results SERP, with region/time/adult-content filters novada_search does not expose, not a generated answer.",
      "name": "novada_scrape_duckduckgo"
    },
    {
      "description": "Extract structured Yandex web search SERP data via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"yandex.com\"). Returns the raw organic-results SERP, with TLD/language/time-range controls novada_search does not expose, not a generated answer.",
      "name": "novada_scrape_yandex"
    },
    {
      "description": "Extract structured YouTube data — video/channel metadata, comments, downloadable video/audio files — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"youtube.com\").",
      "name": "novada_scrape_youtube"
    },
    {
      "description": "Extract structured Instagram data — profiles, posts, reels, and comments — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"instagram.com\").",
      "name": "novada_scrape_instagram"
    },
    {
      "description": "Extract structured Facebook data — public profile pages, posts, comments, and events — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"facebook.com\").",
      "name": "novada_scrape_facebook"
    },
    {
      "description": "Extract structured TikTok data — profile info, post/video details, and post lists by profile, hashtag, or search URL — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"tiktok.com\").",
      "name": "novada_scrape_tiktok"
    },
    {
      "description": "Extract structured X (Twitter) data — a single post and profile lookups by username or URL — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"x.com\").",
      "name": "novada_scrape_x"
    },
    {
      "description": "Extract structured Walmart data — product details by keyword search, category URL, SKU, zip-code-specific pricing, or direct product URL — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"walmart.com\").",
      "name": "novada_scrape_walmart"
    },
    {
      "description": "Extract structured LinkedIn data — job listings (by location/filters, jobs search-results URL, or a single job posting URL) and company profile info by URL — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"linkedin.com\").",
      "name": "novada_scrape_linkedin"
    },
    {
      "description": "Extract structured GitHub repository data — repository details by URL, or multiple repositories from a GitHub search-results URL — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"github.com\").",
      "name": "novada_scrape_github"
    },
    {
      "description": "Extract the actual AI-generated answer Perplexity returns for a query — by a Perplexity query URL or a raw search term — via a closed, typed `operation` enum (same engine as novada_scrape, pinned to platform=\"perplexity.ai\"). Scrapes Perplexity's own live-rendered answer page (the model's actual response text) — NOT a web search results list and NOT an indexed-page brand-mention scan.",
      "name": "novada_scrape_perplexity"
    },
    {
      "description": "Route your own HTTP requests through residential or mobile IPs — geo-targeting, IP rotation, bypassing IP-based rate limits. Returns a proxy URL, shell exports, or a curl --proxy flag.",
      "name": "novada_proxy"
    },
    {
      "description": "Check whether a factual claim is supported by web sources. Runs 3 parallel searches (supporting, skeptical, fact-check angles) and returns a verdict: supported / unsupported / contested / insufficient_data.",
      "name": "novada_verify"
    },
    {
      "description": "Interact with a web page — click, fill forms, scroll, screenshot, or run JavaScript. Chain multiple actions in one call.",
      "name": "novada_browser"
    },
    {
      "description": "Lists all available Novada tools — name, description, category, group, and status. Useful at the start of a task to find the right tool, or whenever another tool's description isn't enough to decide between two options.",
      "name": "novada_discover"
    },
    {
      "description": "Simplified browser automation — 5 actions (click, scroll, wait, type, screenshot). Use only if you need this simpler interface or novada_browser is unavailable.",
      "name": "novada_browser_flow"
    },
    {
      "description": "Search PUBLIC indexed pages on AI-company domains (chatgpt.com/openai.com, perplexity.ai, anthropic.com, etc.) for brand mentions and sentiment. NOT page-change monitoring (novada_monitor) and does NOT query live AI models — a brand absent from indexed pages may still be discussed live; this only reflects indexed-page coverage.",
      "name": "novada_ai_monitor"
    },
    {
      "description": "Detect changes on a web page over time. Extracts content, computes a hash, and compares it with the previous check.",
      "name": "novada_monitor"
    },
    {
      "description": "Onboarding and key-validation tool — useful at the start of a session, or whenever another tool reports a missing/invalid key.",
      "name": "novada_setup"
    },
    {
      "description": "Single-call account & billing dashboard. Composes wallet balance, plan balances, capture logs, and health entitlements via the `section` param.",
      "name": "novada_account"
    },
    {
      "description": "⚠️ WRITE — Create a proxy sub-account. Two-step approval-token gate.",
      "name": "novada_proxy_account_create"
    },
    {
      "description": "List proxy sub-accounts (wraps developer-api POST /v1/proxy_account/list).",
      "name": "novada_proxy_account_list"
    },
    {
      "description": "Manage the proxy IP whitelist — add/list/delete/remark — for Residential (1), Unlimited (4), and Static ISP (5).",
      "name": "novada_ip_whitelist"
    },
    {
      "description": "Get or reset the Capture API key (wraps POST /v1/capture/get_apikey and /v1/capture/reset_apikey).",
      "name": "novada_capture_apikey"
    },
    {
      "description": "Manage static ISP IPs (wraps /v1/static_house/* developer-api endpoints).",
      "name": "novada_static_ip_mgmt"
    },
    {
      "description": "Per-process / per-session usage telemetry: tool-call counts, the last-N calls, and process uptime.",
      "name": "novada_session_stats"
    },
    {
      "description": "Record search-result quality so future ranking can learn from it. Returns a thank-you/echo confirmation with an agent_instruction.",
      "name": "novada_search_feedback"
    }
  ],
  "topics": [
    "search",
    "extract",
    "crawl",
    "map",
    "research",
    "proxy",
    "anti-bot",
    "geo-targeting",
    "rag",
    "ai-agents"
  ]
}
